/**
 * ANSI escape code to HTML converter.
 *
 * Converts terminal ANSI color/style codes to HTML with inline styles.
 * Supports:
 * - Standard foreground colors (30-37) and bright variants (90-97)
 * - Standard background colors (40-47) and bright variants (100-107)
 * - 256-color palette (38;5;N and 48;5;N)
 * - RGB true color (38;2;R;G;B and 48;2;R;G;B)
 * - Text styles: bold (1), dim (2), italic (3), underline (4)
 * - Reset (0)
 */

// Standard ANSI color palette (0-15)
const ANSI_COLORS = [
  '#000000', // 0: black
  '#800000', // 1: red
  '#008000', // 2: green
  '#808000', // 3: yellow
  '#000080', // 4: blue
  '#800080', // 5: magenta
  '#008080', // 6: cyan
  '#c0c0c0', // 7: white
  '#808080', // 8: bright black
  '#ff0000', // 9: bright red
  '#00ff00', // 10: bright green
  '#ffff00', // 11: bright yellow
  '#0000ff', // 12: bright blue
  '#ff00ff', // 13: bright magenta
  '#00ffff', // 14: bright cyan
  '#ffffff', // 15: bright white
];

/**
 * Convert 256-color index to hex.
 */
function color256ToHex(index: number): string {
  // Standard colors (0-15)
  if (index < 16) {
    return ANSI_COLORS[index];
  }

  // Color cube (16-231): 6x6x6 = 216 colors
  if (index < 232) {
    const cubeIndex = index - 16;
    const r = Math.floor(cubeIndex / 36);
    const g = Math.floor((cubeIndex % 36) / 6);
    const b = cubeIndex % 6;
    const toComponent = (n: number) => (n === 0 ? 0 : 55 + n * 40);
    const toHex = (n: number) => toComponent(n).toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  }

  // Grayscale (232-255): 24 shades
  const gray = 8 + (index - 232) * 10;
  const grayHex = gray.toString(16).padStart(2, '0');
  return `#${grayHex}${grayHex}${grayHex}`;
}

/**
 * Escape HTML special characters.
 */
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

interface TextStyle {
  fg: string | null;
  bg: string | null;
  bold: boolean;
  dim: boolean;
  italic: boolean;
  underline: boolean;
}

function createEmptyStyle(): TextStyle {
  return {
    fg: null,
    bg: null,
    bold: false,
    dim: false,
    italic: false,
    underline: false,
  };
}

function styleToInlineCSS(style: TextStyle): string {
  const parts: string[] = [];
  if (style.fg) parts.push(`color:${style.fg}`);
  if (style.bg) parts.push(`background-color:${style.bg}`);
  if (style.bold) parts.push('font-weight:bold');
  if (style.dim) parts.push('opacity:0.6');
  if (style.italic) parts.push('font-style:italic');
  if (style.underline) parts.push('text-decoration:underline');
  return parts.join(';');
}

function hasStyle(style: TextStyle): boolean {
  return (
    style.fg !== null ||
    style.bg !== null ||
    style.bold ||
    style.dim ||
    style.italic ||
    style.underline
  );
}

/**
 * Parse ANSI SGR (Select Graphic Rendition) codes and update style.
 */
function applySgrCode(params: number[], style: TextStyle): void {
  let i = 0;
  while (i < params.length) {
    const code = params[i];

    if (code === 0) {
      // Reset all
      style.fg = null;
      style.bg = null;
      style.bold = false;
      style.dim = false;
      style.italic = false;
      style.underline = false;
    } else if (code === 1) {
      style.bold = true;
    } else if (code === 2) {
      style.dim = true;
    } else if (code === 3) {
      style.italic = true;
    } else if (code === 4) {
      style.underline = true;
    } else if (code === 22) {
      // Reset bold/dim
      style.bold = false;
      style.dim = false;
    } else if (code === 23) {
      style.italic = false;
    } else if (code === 24) {
      style.underline = false;
    } else if (code >= 30 && code <= 37) {
      // Standard foreground colors
      style.fg = ANSI_COLORS[code - 30];
    } else if (code === 38) {
      // Extended foreground color
      if (params[i + 1] === 5 && params.length > i + 2) {
        // 256-color: 38;5;N
        style.fg = color256ToHex(params[i + 2]);
        i += 2;
      } else if (params[i + 1] === 2 && params.length > i + 4) {
        // RGB: 38;2;R;G;B
        const r = params[i + 2];
        const g = params[i + 3];
        const b = params[i + 4];
        style.fg = `rgb(${r},${g},${b})`;
        i += 4;
